/* USER CODE BEGIN 4 */
void EXTI0_IRQHandler(void){

	// TODO: Debounce using HAL_GetTick()
	current_time = HAL_GetTick();
	if (current_time - last_button_press < debounce_delay) {
	        HAL_GPIO_EXTI_IRQHandler(Button0_Pin); // Clear interrupt flags
	        return; // Ignore this press (debouncing)
	}
	last_button_press = current_time;


	// TODO: Disable DMA transfer and abort IT, then start DMA in IT mode with new LUT and re-enable transfer
	// HINT: Consider using C's "switch" function to handle LUT changes
	  __HAL_TIM_DISABLE_DMA(&htim2, TIM_DMA_CC1);      // disable DMA request from TIM2 CC1
	  HAL_DMA_Abort_IT(&hdma_tim2_ch1);                // abort ongoing DMA transfer (non-blocking, sends abort)

	  // Changing waves on button press
	  wave_index++;
	  if (wave_index >= 7){
		  wave_index = 1; // Loop back to 1 after reaching final index
	  }
      if (wave_index >= 3){
    	  TIM2_Ticks = (uint32_t) (TIM2CLK) /(NS_s)*(F_SIGNAL_S);
    	  __HAL_TIM_SET_AUTORELOAD(&htim2,TIM2_Ticks);
      }
      else{
    	  TIM2_Ticks = (uint32_t)(TIM2CLK)/(NS_L)*(F_SIGNAL_L);
    	  __HAL_TIM_SET_AUTORELOAD(&htim2,TIM2_Ticks);
      }
	  switch (wave_index){
	  case 1:
		  // Corresponds to sine wave
		  HAL_DMA_Start_IT(&hdma_tim2_ch1,(uint32_t) Sin_LUT, (uint32_t) DestAddress, NS_s);
		  lcd_update_line(LCD_CHARS[0]);
		  break;

	  case 2:
		  // Corresponds to Sawtooth wave
		  TIM2_Ticks =
		  htim2.Init.Period = TIM2_Ticks - 1;
		  HAL_DMA_Start_IT(&hdma_tim2_ch1, (uint32_t) Saw_LUT,(uint32_t) DestAddress, NS_s);
		  lcd_update_line(LCD_CHARS[1]);
		  break;

	  case 3:
		  // Corresponds to Triangular wave
		  //HAL_DMA_Start_IT(&hdma_tim2_ch1, (uint32_t) Triangle_LUT, (uint32_t) DestAddress, NS);
		  lcd_update_line(LCD_CHARS[2]);
		  break;

	  case 4:
		  // Corresponds to Guitar wave
		  //HAL_DMA_Start_IT(&hdma_tim2_ch1, (uint32_t) Piano_LUT, (uint32_t) DestAddress, NS);
		  lcd_update_line(LCD_CHARS[3]);
		  break;

	  case 5:
		  // Corresponds to piano wave
		  //HAL_DMA_Start_IT(&hdma_tim2_ch1,(uint32_t) Guitar_LUT, (uint32_t) DestAddress, NS);
          lcd_update_line(LCD_CHARS[4]);
          break;

	  case 6:
		  // Corresponds to drum wave
		  //HAL_DMA_Start_IT(&hdma_tim2_ch1, (uint32_t) Drum_LUT, (uint32_t) DestAddress, NS);
		  lcd_update_line(LCD_CHARS[5]);
		  break;

	  default:
		  break;

     }

    __HAL_TIM_ENABLE_DMA(&htim2, TIM_DMA_CC1);
	HAL_GPIO_EXTI_IRQHandler(Button0_Pin); // Clear interrupt flags
}
/* USER CODE END 4 */

